update public.profiles p set full_name = trim(u.raw_user_meta_data ->> 'full_name') from auth.users u where u.id = p.id and (p.full_name is null or btrim(p.full_name) = '') and coalesce(trim(u.raw_user_meta_data ->> 'full_name'), '') <> ''; update public.profiles p set full_name = initcap( btrim( regexp_replace( regexp_replace(split_part(u.email, '@', 1), '[._+-]+', ' ', 'g'), '\s*\d+$', '', 'g' ) ) ) from auth.users u where u.id = p.id and (p.full_name is null or btrim(p.full_name) = '') and coalesce(u.email, '') <> '' and btrim(regexp_replace(split_part(u.email, '@', 1), '[._+-]+', ' ', 'g')) <> ''; update public.profiles set full_name = 'Team member' where full_name is null or btrim(full_name) = ''; alter table public.profiles alter column full_name set not null; alter table public.profiles drop constraint if exists profiles_full_name_not_blank; alter table public.profiles add constraint profiles_full_name_not_blank check (btrim(full_name) <> ''); alter table public.profiles add column if not exists phone text; insert into storage.buckets (id, name, public) values ('profile-avatars', 'profile-avatars', true) on conflict (id) do nothing; drop policy if exists "profile-avatars: public read" on storage.objects; create policy "profile-avatars: public read" on storage.objects for select using (bucket_id = 'profile-avatars'); create or replace function public.storage_object_owner_id(object_name text) returns uuid language plpgsql immutable as $$ declare base text; begin base := split_part(object_name, '.', 1); if base !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then return null; end if; return base::uuid; end; $$; grant execute on function public.storage_object_owner_id(text) to authenticated; drop policy if exists "profile-avatars: own write" on storage.objects; create policy "profile-avatars: own write" on storage.objects for all using ( bucket_id = 'profile-avatars' and public.storage_object_owner_id(name) = auth.uid() ) with check ( bucket_id = 'profile-avatars' and public.storage_object_owner_id(name) = auth.uid() ); drop policy if exists "profile-avatars: management write" on storage.objects; create policy "profile-avatars: management write" on storage.objects for all using (bucket_id = 'profile-avatars' and public.is_management()) with check (bucket_id = 'profile-avatars' and public.is_management()); drop policy if exists "profiles: management update any" on profiles; create policy "profiles: management update any" on profiles for update using (public.is_management()) with check (public.is_management());
